import{_ as t,o as e,c as r,a2 as a}from"./chunks/framework.A5mep7Fe.js";const p=JSON.parse('{"title":"🐹 04 · Go（云原生与高并发服务）","description":"","frontmatter":{},"headers":[],"relativePath":"06-开发岗-编程语言与工程/04-Go.md","filePath":"06-开发岗-编程语言与工程/04-Go.md","lastUpdated":1786806808000}'),n={name:"06-开发岗-编程语言与工程/04-Go.md"};function l(i,o,s,c,g,u){return e(),r("div",null,[...o[0]||(o[0]=[a('<h1 id="🐹-04-·-go-云原生与高并发服务" tabindex="-1">🐹 04 · Go（云原生与高并发服务） <a class="header-anchor" href="#🐹-04-·-go-云原生与高并发服务" aria-label="Permalink to &quot;🐹 04 · Go（云原生与高并发服务）&quot;">​</a></h1><blockquote><p>AI 公司的大量「中间件/网关/基础设施」用 Go：高并发、部署简单、云原生友好。Agent 平台、推理网关常用 Go。</p></blockquote><hr><h2 id="一、核心考点" tabindex="-1">一、核心考点 <a class="header-anchor" href="#一、核心考点" aria-label="Permalink to &quot;一、核心考点&quot;">​</a></h2><ul><li><strong>goroutine</strong>：轻量协程（几 KB 栈），海量并发。</li><li><strong>Channel</strong>：CSP 并发模型，goroutine 间通信。</li><li><strong>调度器（G-M-P）</strong>：用户态调度，万级协程高效运行。</li><li><strong>sync 包</strong>：Mutex、WaitGroup、Once、原子操作。</li><li><strong>GC</strong>：并发三色标记，低停顿（适合服务）。</li><li><strong>interface 与组合</strong>：Go 的「多态」靠组合而非继承。</li><li><strong>错误处理</strong>：显式 error 返回（无异常）。</li></ul><h2 id="二、ai-结合点" tabindex="-1">二、AI 结合点 <a class="header-anchor" href="#二、ai-结合点" aria-label="Permalink to &quot;二、AI 结合点&quot;">​</a></h2><ul><li><strong>AI 推理网关/代理</strong>：高并发转发 LLM 请求、限流、鉴权、成本统计。</li><li><strong>Agent 平台后端</strong>：多 Agent 编排服务、任务队列、实时通信。</li><li><strong>云原生基础设施</strong>：K8s 生态（用 Go 写）、向量库/中间件。</li><li>框架：用 Gin / Fiber 写 REST，用 gRPC 做内部通信。</li></ul><h2 id="三、高频追问" tabindex="-1">三、高频追问 <a class="header-anchor" href="#三、高频追问" aria-label="Permalink to &quot;三、高频追问&quot;">​</a></h2><p><strong>Q1：goroutine 和线程区别？</strong></p><blockquote><p>goroutine 由 Go 运行时调度、栈初始仅几 KB 可增长，单机可跑百万级；OS 线程更重（MB 级），受内核调度限制。</p></blockquote><p><strong>Q2：Channel 关闭与遍历注意什么？</strong></p><blockquote><p>向已关闭 channel 发送会 panic；用 <code>v, ok := &lt;-ch</code> 判关闭；多生产者用 <code>close</code> 需谨慎（通常单处关闭）；for-range 自动在关闭后退出。</p></blockquote><p><strong>Q3：Go 适合写 LLM 推理服务吗？</strong></p><blockquote><p>非常适合做「网关/编排/代理」层（高并发、易部署）；但模型计算本身仍在 Python/C++ 推理引擎，Go 负责调度与转发。</p></blockquote><hr><p>➡️ 下一步：<a href="./05-嵌入式">05-嵌入式</a></p>',16)])])}const d=t(n,[["render",l]]);export{p as __pageData,d as default};
